const CANONICAL='Luke883i/iKant_LE';
const CANONICAL_URL='https://github.com/Luke883i/iKant_LE';
export const FIRST_CONTACT_CAPSULE=Object.freeze(['README.md','BOOTSTRAP.json','ADMISSION.json','AGENTS.md','TERMS.md']);
export const FIRST_CONTACT_FORBIDDEN=Object.freeze(['CLONE_REPOSITORY','GIT_FETCH','GIT_LS_REMOTE','GH_CLI','RAW_WEB_READ','DIRECT_DOWNLOAD','ARCHIVE_DOWNLOAD','SHELL_HTTP_DOWNLOAD','LIST_TREE','SEARCH_REPOSITORY','READ_ARBITRARY_REPOSITORY_FILE','READ_HISTORY','READ_ISSUE_PR','MATERIALIZE_CHECKOUT']);
export const REPOSITORY_TRANSPORT=Object.freeze({required:'GITHUB_API',allowed:['GITHUB_CONNECTOR','GITHUB_REST_API'],connector_is_api_adapter:true,fallback:null,api_unavailable_terminal:'HOST_INCOMPATIBLE',unavailable_tools_must_not_be_attempted:true});
export const SOURCE_HEAD_BINDING=Object.freeze({action:'READ_BRANCH_HEAD',branch:'main',transport:'GITHUB_API',required:true,before_orientation_files:true,pin_all_repository_reads:true});
function normalize(value){let x=String(value??'').normalize('NFKC').replace(/[\u200B-\u200D\u2060\uFEFF]/g,'');try{x=decodeURIComponent(x);}catch{}return x.toLowerCase();}
export function referencesCanonicalRepository(input){const x=normalize(input);return /(?:https?:\/\/)?github\.com\/luke883i\/ikant_le(?:\.git)?(?=$|[\s\/?#)\]}>.,;:'"!`])/i.test(x)||/git@github\.com:luke883i\/ikant_le(?:\.git)?(?=$|[\s)\]}>.,;:'"!`])/i.test(x)||/(^|[\s([{'"`.,;:!?<>])luke883i\/ikant_le(?=$|[\s)\]}>,.;:'"!?`])/i.test(x)||/(^|[\s([{'"`.,;:!?<>])ikant_le(?=$|[\s)\]}>,.;:'"!?`])/i.test(x);}
export function compileFirstContactPlan(input){if(!referencesCanonicalRepository(input))return{schema:'ikant-le-first-contact/v2',recognized:false,terminal:'NOT_TARGET_REPOSITORY'};return{schema:'ikant-le-first-contact/v2',recognized:true,repository:CANONICAL,repository_url:CANONICAL_URL,terminal:'CANONICAL_PREACCEPT',pending_intent:String(input??''),preserve_pending_intent:true,repository_transport:{...REPOSITORY_TRANSPORT},source_head_binding:{...SOURCE_HEAD_BINDING},default_acquisition:FIRST_CONTACT_CAPSULE.map(target=>({action:'READ_ORIENTATION_FILE',target,transport:'GITHUB_API',direct_path_only:true,exact_ref:'SOURCE_HEAD'})),optional_metadata:{action:'READ_ORIENTATION_METADATA',transport:'GITHUB_API',fields:['repository_full_name','default_branch','description'],max_reads:1},present_terms_after_capsule:true,freeze_after_terms_presentation:true,required_next_human_message:'I ACCEPT',embedded_acceptance_is_invalid:true,auto_after_acceptance:['ACTIVATE_FIRST','PARALLEL_RUNTIME_CAPSULE','IMPORT_PREACCEPT_HANDOFF','AUTO_PROBE','AUTO_INITIALIZE','RESUME_PENDING_INTENT_IF_ANY'],post_accept_fastboot:{manifest:'BOOTSTRAP.json',mode:'ACTIVATE_FIRST',remote_acquisition_rounds_max:1,parallel_fetch_required:true,exact_ref:'SOURCE_HEAD',generic_discovery_before_active:false,tests_before_active:false,qualification_before_active:false},forbidden_before_acceptance:[...FIRST_CONTACT_FORBIDDEN],generic_repository_discovery_forbidden:true,host_constraints_precede_local_contract:true};}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {classifyDeadlineEvidence,DEADLINE_RESULT} from './deadline-integrity.mjs';
import {validateFastbootConvergence,validateFastbootChannelLedger,validateFastbootStep,validateFastbootByteBridgeReceipt} from './fastboot-convergence.mjs';

const WORKSPACE=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const HEX40=/^[a-f0-9]{40}$/;
const HEX64=/^[a-f0-9]{64}$/;
export const CHAT_BOOTSTRAP_DEADLINE_MS=120000;
export const ACTIVATION_SLO_MS=120000;
export const ACTIVATION_EXECUTOR_SCHEMA='ikant-le-activation-executor/v1';
export const ACTIVATION_BYTE_PATHS=Object.freeze(['LOCAL_DIRECT','VERIFIED_OPAQUE_RELAY']);
export const CHAT_BOOTSTRAP_EVIDENCE_V2='ikant-le-chat-bootstrap-evidence/v2';
const sha256=b=>crypto.createHash('sha256').update(b).digest('hex');
const FLEX_TRANSFER_SCHEMA='ikant-le-source-bound-transfer/v2';
const FLEX_TRANSPORTS=new Set(['GITHUB_API_BASE64','GITHUB_GIT_BLOB_API','PINNED_PERMALINK','PINNED_GITHUB_ZIP','HOST_FILE_BRIDGE','WARM_CACHE_EXACT']);
function digestWithout(value,field='receipt_sha256'){const copy=structuredClone(value||{});delete copy[field];return sha256(Buffer.from(JSON.stringify(copy)));}
function bad(errors,code='HOST_INCOMPATIBLE',extra={}){return{ok:false,errors:[...new Set(errors)],terminal:code,...extra};}
function expectedFlexObjects(d){const rows=[];if(d?.loader)rows.push({path:d.loader.path,blob_sha1:d.loader.blob_sha1});for(const s of d?.shards||[])rows.push({path:s.path,blob_sha1:s.blob_sha1});return rows;}
function orientationObjectSetDigest(rows){return sha256(Buffer.from(JSON.stringify((rows||[]).map(x=>({path:x.path,blob_sha1:x.blob_sha1,bytes:x.bytes})))));}
function expectedExecutorRuntimeObjects(d){const rows=[];if(d?.loader){let bytes=null;try{bytes=fs.readFileSync(path.join(WORKSPACE,d.loader.path)).length;}catch{}rows.push({path:d.loader.path,blob_sha1:d.loader.blob_sha1,bytes});}for(const s of d?.shards||[])rows.push({path:s.path,blob_sha1:s.blob_sha1,bytes:s.source_bytes});return rows;}
function normalizeObjectRows(rows){return(Array.isArray(rows)?rows:[]).map(x=>({path:x?.path,blob_sha1:x?.blob_sha1,bytes:x?.bytes}));}
function sameObjectRows(a,b){const x=normalizeObjectRows(a),y=normalizeObjectRows(b);if(x.length!==y.length)return false;const by=new Map(x.map(r=>[r.path,r]));if(by.size!==x.length)return false;for(const r of y){const q=by.get(r.path);if(!q||q.blob_sha1!==r.blob_sha1||q.bytes!==r.bytes)return false;}return true;}
export function validateActivationExecutorReceipt(receipt,{sourceHead,runtimeRootSha256,runtimeRootDescriptor=null,orientationObjects=[]}={}){
 const e=[];
 if(!receipt||receipt.schema!==ACTIVATION_EXECUTOR_SCHEMA)e.push('schema');
 if(receipt?.authority!==0)e.push('authority');
 if(receipt?.repository!=='Luke883i/iKant_LE')e.push('repository');
 if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');
 if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');
 if(receipt?.execution_plane!=='SESSION_LOCAL_NODE')e.push('execution_plane');
 if(receipt?.capability_probe_passed!==true||receipt?.capability_probe_before_acquisition!==true)e.push('capability_probe');
 if(receipt?.content_addressed!==true)e.push('content_addressing');
 const bytePath=String(receipt?.byte_path||'');
 if(!ACTIVATION_BYTE_PATHS.includes(bytePath))e.push('byte_path');
 if(receipt?.model_rewrite_allowed!==false)e.push('model_rewrite');
 if(receipt?.semantic_equivalence_allowed!==false)e.push('semantic_equivalence');
 if(receipt?.source_arrival_samehash_required!==true||receipt?.source_arrival_samehash_verified!==true)e.push('source_arrival_samehash');
 if(bytePath==='LOCAL_DIRECT'){
  if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');
  if(receipt?.model_role!=='NONE')e.push('model_role');
  if(receipt?.opaque_relay_roundtrip_verified!==false)e.push('opaque_relay_roundtrip');
 }else if(bytePath==='VERIFIED_OPAQUE_RELAY'){
  if(receipt?.model_mediated_bytes!==true)e.push('model_mediated_bytes_truth');
  if(receipt?.model_role!=='OPAQUE_TRANSPORT_ONLY')e.push('model_role');
  if(receipt?.opaque_relay_roundtrip_verified!==true)e.push('opaque_relay_roundtrip');
 }
 if(receipt?.retry_semantics!=='IDEMPOTENT_BY_OBJECT_IDENTITY')e.push('retry_semantics');
 if(receipt?.acquisition_complete!==true)e.push('acquisition_complete');
 if(!sameObjectRows(receipt?.orientation_objects,orientationObjects))e.push('orientation_identity');
 const expected=expectedExecutorRuntimeObjects(runtimeRootDescriptor);
 if(!runtimeRootDescriptor||runtimeRootDescriptor.schema!=='ikant-le-runtime-root/v1'||!sameObjectRows(receipt?.runtime_objects,expected))e.push('runtime_objects');
 const slo=receipt?.slo_elapsed_ms;if(slo!==null&&slo!==undefined&&(!Number.isFinite(slo)||slo<0))e.push('slo_elapsed');
 if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt.receipt_sha256)e.push('receipt_digest');
 if(!e.length)return{ok:true,receipt_sha256:receipt.receipt_sha256,orientation_object_set_sha256:orientationObjectSetDigest(orientationObjects),slo_elapsed_ms:Number.isFinite(slo)?slo:null,slo_exceeded:Number.isFinite(slo)&&slo>ACTIVATION_SLO_MS,integrity_time_gate_required:false,mode:'LOCAL_EXECUTOR',byte_path:bytePath};
 const unavailable=e.every(x=>['capability_probe','acquisition_complete'].includes(x));
 return bad(e,unavailable?'HOST_UNAVAILABLE':'BLOCKED_INTEGRITY',{integrity_time_gate_required:false});
}
function validateOrientationReadback(workspace,rows){const e=[];for(const x of rows||[]){let b;try{b=fs.readFileSync(path.join(workspace,x.path));}catch{e.push('missing:'+x.path);continue;}if(gitBlobSha1(b)!==x.blob_sha1||b.length!==x.bytes)e.push('identity:'+x.path);}return e.length?bad(e):{ok:true,orientation_object_set_sha256:orientationObjectSetDigest(rows)};}

export function validateTransferRemoteHistory(receipt,{sourceHead,runtimeRootSha256,runtimeRootDescriptor=null,maxReads=8,maxRounds=1,flexMaxReads=40,flexMaxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 const e=[];let material=null;
 if(receipt?.schema===FLEX_TRANSFER_SCHEMA){if(receipt?.authority!==0||receipt?.transport_authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!FLEX_TRANSPORTS.has(receipt?.mode))e.push('mode');if(receipt?.identity_authority!=='CONTENT_ADDRESSING')e.push('identity_authority');if(receipt?.exact_ref!==true)e.push('exact_ref');if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');if(receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('content');if(!Number.isInteger(receipt?.remote_reads)||receipt.remote_reads<0||receipt.remote_reads>flexMaxReads)e.push('remote_reads');if(!Number.isInteger(receipt?.remote_rounds)||receipt.remote_rounds<0||receipt.remote_rounds>flexMaxRounds)e.push('remote_rounds');if(!Number.isFinite(receipt?.elapsed_ms)||receipt.elapsed_ms<0||receipt.elapsed_ms>deadlineMs)e.push('elapsed');const expected=expectedFlexObjects(runtimeRootDescriptor),exp=new Map(expected.map(x=>[x.path,x])),rows=receipt?.remote_objects;if(!runtimeRootDescriptor||runtimeRootDescriptor.schema!=='ikant-le-runtime-root/v1'||!Array.isArray(rows)||rows.length!==exp.size)e.push('remote_objects');else{const seen=new Set();for(const r of rows){const x=exp.get(r?.path);if(!x||seen.has(r.path)){e.push('object_set');continue;}seen.add(r.path);if(r.blob_sha1!==x.blob_sha1||!HEX64.test(String(r.sha256||''))||!Number.isInteger(r.bytes)||r.bytes<1)e.push('object_identity');}}if(['PINNED_PERMALINK','PINNED_GITHUB_ZIP'].includes(receipt?.mode)&&receipt?.locator_pinned!==true)e.push('locator_pin');if(receipt?.mode==='PINNED_GITHUB_ZIP'){const a=receipt?.archive_policy;if(!a||a.selective_extract!==true||a.path_safe!==true||a.special_entries_rejected!==true||a.duplicates_rejected!==true||a.encrypted_entries_rejected!==true)e.push('archive_policy');}material={schema:receipt?.schema,source_head:receipt?.source_head,runtime_root_sha256:receipt?.runtime_root_sha256,mode:receipt?.mode,transport_authority:receipt?.transport_authority,identity_authority:receipt?.identity_authority,exact_ref:receipt?.exact_ref,model_mediated_bytes:receipt?.model_mediated_bytes,complete:receipt?.complete,bytes_exact:receipt?.bytes_exact,remote_objects:receipt?.remote_objects,remote_rounds:receipt?.remote_rounds,remote_reads:receipt?.remote_reads,locator_pinned:receipt?.locator_pinned,archive_policy:receipt?.archive_policy,elapsed_ms:receipt?.elapsed_ms,authority:receipt?.authority};}
 else{if(!receipt||receipt.schema!=='ikant-le-source-bound-transfer/v1')return bad(['schema']);if(receipt?.authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!['COLD_API','WARM_CACHE_EXACT'].includes(receipt?.mode))e.push('mode');if(receipt?.transport!=='GITHUB_API')e.push('transport');if(receipt?.exact_ref!==true)e.push('exact_ref');if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');if(receipt?.fallback_used!==false)e.push('fallback_used');if(receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('content');const rounds=receipt?.remote_rounds,reads=receipt?.remote_reads;if(!Number.isInteger(rounds)||rounds<0||rounds>maxRounds)e.push('remote_rounds');if(!Number.isInteger(reads)||reads<0||reads>maxReads)e.push('remote_reads');if(receipt?.mode==='COLD_API'&&(rounds!==1||reads<1))e.push('cold_transfer');if(receipt?.mode==='WARM_CACHE_EXACT'&&(rounds!==0||reads!==0))e.push('warm_transfer');if(!Number.isFinite(receipt?.elapsed_ms)||receipt.elapsed_ms<0||receipt.elapsed_ms>deadlineMs)e.push('elapsed');material={schema:receipt?.schema,source_head:receipt?.source_head,runtime_root_sha256:receipt?.runtime_root_sha256,mode:receipt?.mode,transport:receipt?.transport,exact_ref:receipt?.exact_ref,model_mediated_bytes:receipt?.model_mediated_bytes,fallback_used:receipt?.fallback_used,complete:receipt?.complete,bytes_exact:receipt?.bytes_exact,remote_rounds:receipt?.remote_rounds,remote_reads:receipt?.remote_reads,elapsed_ms:receipt?.elapsed_ms,authority:receipt?.authority};}
 if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt?.receipt_sha256)e.push('receipt_digest');if(e.length)return bad(e);return{ok:true,remote_history_sha256:sha256(Buffer.from(JSON.stringify(material))),remote_reads:receipt.remote_reads,remote_rounds:receipt.remote_rounds,mode:receipt.mode};}
export function validateActivationContinuationReceipt(receipt,{sourceHead,termsDigest,acceptanceEventId,acceptanceOriginReceiptSha256,remoteHistorySha256,minElapsedMs=0,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){const e=[];if(!receipt||receipt.schema!=='ikant-le-activation-continuation/v1')e.push('schema');if(receipt?.authority!==0)e.push('authority');if(receipt?.acceptance_event_id!==acceptanceEventId)e.push('acceptance_event_binding');if(receipt?.acceptance_origin_receipt_sha256!==acceptanceOriginReceiptSha256||!HEX64.test(String(acceptanceOriginReceiptSha256||'')))e.push('acceptance_origin_binding');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.terms_digest!==termsDigest||!HEX64.test(String(termsDigest||'')))e.push('terms_digest');if(receipt?.remote_history_sha256!==remoteHistorySha256||!HEX64.test(String(remoteHistorySha256||'')))e.push('remote_history_binding');if(receipt?.clock!=='MONOTONIC'||receipt?.observed_at_resume!==true)e.push('clock');if(receipt?.no_new_remote_acquisition!==true)e.push('remote_reacquisition');const elapsed=receipt?.elapsed_since_accept_ms;if(!Number.isFinite(elapsed)||elapsed<0)e.push('elapsed_unavailable');if(Number.isFinite(elapsed)&&elapsed<Number(minElapsedMs||0))e.push('elapsed_regression');if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt?.receipt_sha256)e.push('receipt_digest');if(Number.isFinite(elapsed)&&elapsed>deadlineMs)return bad([...e,'deadline_exceeded'],'BOOTSTRAP_DEADLINE_EXCEEDED',{deadline_result:DEADLINE_RESULT.EXCEEDED});return e.length?bad(e):{ok:true,elapsed_before_runtime_ms:elapsed,receipt_sha256:receipt.receipt_sha256,remote_history_sha256:receipt.remote_history_sha256,acceptance_event_id:receipt.acceptance_event_id};}

export function validateAcceptanceOriginReceipt(receipt,{sourceHead,termsDigest,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
  const classified=classifyDeadlineEvidence(receipt,{sourceHead,termsDigest,deadlineMs});
  if(classified.result!==DEADLINE_RESULT.PASS)return{ok:false,...classified,receipt_sha256:receipt?.receipt_sha256||null};
  if(receipt?.schema==='ikant-le-acceptance-origin/v2'){
    const t=receipt?.origin_ticket,x=structuredClone(t||{});delete x.ticket_sha256;
    if(!HEX64.test(String(t?.ticket_sha256||''))||sha256(Buffer.from(JSON.stringify(x)))!==t.ticket_sha256)return{ok:false,result:DEADLINE_RESULT.ORIGIN_INVALID,terminal:true,reason:'origin_ticket_digest',receipt_sha256:receipt?.receipt_sha256||null};
  }
  if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt.receipt_sha256)return{ok:false,result:DEADLINE_RESULT.ORIGIN_INVALID,terminal:true,reason:'receipt_digest',receipt_sha256:receipt?.receipt_sha256||null};
  return{ok:true,result:DEADLINE_RESULT.PASS,terminal:false,elapsed_ms:classified.elapsed_ms,event_id:receipt.event_id,receipt_sha256:receipt.receipt_sha256};
}

function validateFlexibleTransfer(receipt,{sourceHead,runtimeRootSha256,descriptor,maxReads=40,maxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 const e=[];if(!receipt||receipt.schema!==FLEX_TRANSFER_SCHEMA)e.push('schema');if(receipt?.authority!==0||receipt?.transport_authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!FLEX_TRANSPORTS.has(receipt?.mode))e.push('mode');if(receipt?.identity_authority!=='CONTENT_ADDRESSING')e.push('identity_authority');if(receipt?.exact_ref!==true)e.push('exact_ref');if(receipt?.bridge_observed!==true)e.push('bridge_observed');if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');if(receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('content');if(!Number.isInteger(receipt?.remote_reads)||receipt.remote_reads<0||receipt.remote_reads>maxReads)e.push('remote_reads');if(!Number.isInteger(receipt?.remote_rounds)||receipt.remote_rounds<0||receipt.remote_rounds>maxRounds)e.push('remote_rounds');
 const elapsed=receipt?.elapsed_ms;if(!Number.isFinite(elapsed)||elapsed<0)e.push('elapsed_unavailable');if(Number.isFinite(elapsed)&&elapsed>deadlineMs)e.push('deadline_exceeded');
 const expected=expectedFlexObjects(descriptor),exp=new Map(expected.map(x=>[x.path,x]));if(!descriptor||descriptor.schema!=='ikant-le-runtime-root/v1'||!descriptor.loader||!Array.isArray(descriptor.shards)||expected.length<2)e.push('descriptor');const rows=receipt?.remote_objects;if(!Array.isArray(rows)||rows.length!==exp.size)e.push('remote_objects');else{const seen=new Set();for(const r of rows){const x=exp.get(r?.path);if(!x||seen.has(r.path)){e.push('object_set');continue;}seen.add(r.path);if(r.blob_sha1!==x.blob_sha1||!HEX64.test(String(r.sha256||''))||!Number.isInteger(r.bytes)||r.bytes<1)e.push('object_identity');}}if(['PINNED_PERMALINK','PINNED_GITHUB_ZIP'].includes(receipt?.mode)&&receipt?.locator_pinned!==true)e.push('locator_pin');if(receipt?.mode==='PINNED_GITHUB_ZIP'){const a=receipt?.archive_policy;if(!a||a.selective_extract!==true||a.path_safe!==true||a.special_entries_rejected!==true||a.duplicates_rejected!==true||a.encrypted_entries_rejected!==true)e.push('archive_policy');}if(receipt?.mode==='HOST_FILE_BRIDGE'&&receipt?.host_readback_verified!==true)e.push('host_readback');if(receipt?.mode==='WARM_CACHE_EXACT'&&receipt?.cache_reopen_verified!==true)e.push('cache_reopen');if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt.receipt_sha256)e.push('receipt_digest');
 return e.length?bad(e,e.includes('deadline_exceeded')?'BOOTSTRAP_DEADLINE_EXCEEDED':'HOST_INCOMPATIBLE',e.includes('deadline_exceeded')?{deadline_result:DEADLINE_RESULT.EXCEEDED}:{}):{ok:true,receipt_sha256:receipt.receipt_sha256,elapsed_ms:elapsed,mode:receipt.mode};
}

export function validateSourceBoundTransfer(receipt,{sourceHead,runtimeRootSha256,runtimeRootDescriptor=null,maxReads=8,maxRounds=1,flexMaxReads=40,flexMaxRounds=1,deadlineMs=CHAT_BOOTSTRAP_DEADLINE_MS}={}){
 if(receipt?.schema===FLEX_TRANSFER_SCHEMA)return validateFlexibleTransfer(receipt,{sourceHead,runtimeRootSha256,descriptor:runtimeRootDescriptor,maxReads:flexMaxReads,maxRounds:flexMaxRounds,deadlineMs});
 const e=[];if(!receipt||receipt.schema!=='ikant-le-source-bound-transfer/v1')return bad(['schema']);if(receipt?.authority!==0)e.push('authority');if(receipt?.source_head!==sourceHead||!HEX40.test(String(sourceHead||'')))e.push('source_head');if(receipt?.runtime_root_sha256!==runtimeRootSha256||!HEX64.test(String(runtimeRootSha256||'')))e.push('runtime_root');if(!['COLD_API','WARM_CACHE_EXACT'].includes(receipt?.mode))e.push('mode');if(receipt?.transport!=='GITHUB_API')e.push('transport');if(receipt?.exact_ref!==true)e.push('exact_ref');if(receipt?.bridge_observed!==true)e.push('bridge_observed');if(receipt?.model_mediated_bytes!==false)e.push('model_mediated_bytes');if(receipt?.fallback_used!==false)e.push('fallback_used');if(receipt?.complete!==true||receipt?.bytes_exact!==true)e.push('content');const rounds=receipt?.remote_rounds,reads=receipt?.remote_reads;if(!Number.isInteger(rounds)||rounds<0||rounds>maxRounds)e.push('remote_rounds');if(!Number.isInteger(reads)||reads<0||reads>maxReads)e.push('remote_reads');if(receipt?.mode==='COLD_API'&&(rounds!==1||reads<1))e.push('cold_transfer');if(receipt?.mode==='WARM_CACHE_EXACT'&&(rounds!==0||reads!==0||receipt?.cache_reopen_verified!==true))e.push('warm_transfer');
 const elapsed=receipt?.elapsed_ms;if(!Number.isFinite(elapsed)||elapsed<0)e.push('elapsed_unavailable');if(Number.isFinite(elapsed)&&elapsed>deadlineMs)e.push('deadline_exceeded');
 if(!HEX64.test(String(receipt?.receipt_sha256||''))||digestWithout(receipt)!==receipt?.receipt_sha256)e.push('receipt_digest');
