export const FASTBOOT_CARRIERS=Object.freeze([
  'WARM_CACHE_EXACT','HOST_FILE_BRIDGE','GITHUB_API_BASE64','GITHUB_GIT_BLOB_API','PINNED_GITHUB_ZIP','PINNED_PERMALINK'
